  "implementation": "def solve(case):
    # Validate input structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'segments' not in case or 'budget' not in case:
        raise ValueError("case must contain 'segments' and 'budget'")
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")
    if not isinstance(budget, int):
        raise ValueError("budget must be an integer")

    # Extract segment data
    names = []
    importances = []
    minima = []
    capacities = []
    for idx, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f"segment {idx} is not a dict")
        for key in ('name','importance','minimum','capacity'):
            if key not in seg:
                raise ValueError(f"segment {idx} missing key '{key}'")
        names.append(seg['name'])
        importances.append(seg['importance'])
        minima.append(seg['minimum'])
        capacities.append(seg['capacity'])

    # Check types of numeric fields
    for i in range(len(segments)):
        if not isinstance(importances[i], (int, float)):
            raise ValueError(f"importance for segment {i} must be numeric")
        if not isinstance(minima[i], int):
            raise ValueError(f"minimum for segment {i} must be integer")
        if not isinstance(capacities[i], int):
            raise ValueError(f"capacity for segment {i} must be integer")
        if minima[i] < 0 or capacities[i] < 0:
            raise ValueError(f"segment {i} has negative minimum or capacity")
        if minima[i] > capacities[i]:
            raise ValueError(f"segment {i} minimum exceeds capacity")

    # Compute sums
    total_min = sum(minima)
    total_cap = sum(capacities)
    if budget < total_min:
        raise ValueError(f"budget {budget} < total minimum {total_min}")
    if budget > total_cap:
        raise ValueError(f"budget {budget} > total capacity {total_cap}")

    # Initialize allocations with minima
    allocations = list(minima)
    remaining = budget - total_min

    # While tokens remain, find best segment by score
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocations[i] >= capacities[i]:
                continue
            next_pos = allocations[i] + 1
            score = importances[i] / next_pos  # float division
            if score > best_score:
                best_score = score
                best_idx = i
            elif score == best_score and best_idx != -1 and i < best_idx:
                # tie-break: earlier index wins (already have best_idx, update if i < best_idx? Actually we want smallest index among ties)
                # But if score == best_score and i < best_idx, we should update
                # The loop goes from 0 upward, so if we find a later index with same score, we keep earlier one.
                # So we should not update when score == best_score because earlier index already chosen.
                # However, if we first encounter a later index with same score, best_idx might be earlier? No, we process increasing i, so first index encountered with max score is smallest i. So we don't need tie-break logic; the first max score wins.
                pass
        if best_idx == -1:
            # Should not happen because remaining>0 and total cap >= budget
            raise RuntimeError("no eligible segment but remaining > 0")
        allocations[best_idx] += 1
        remaining -= 1

    # Build by_name dictionary
    by_name = {}
    for i in range(n):
        by_name[names[i]] = allocations[i]

    total = sum(allocations)

    # Return result
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total
    }"
}
